def _fit(usage_i, r):
    for k in usage_i:
        if r[k] == 0:
            return False
    return True


def _dec(usage_i, r):
    if len(usage_i) == 1:
        k0 = usage_i[0]
        return r[:k0] + (r[k0] - 1,) + r[k0 + 1:]
    lst = list(r)
    for k in usage_i:
        lst[k] -= 1
    return tuple(lst)


def _plan_bnb(b, usage, K, n, r0, bound, limit):
    """Branch and bound, take-first.  Returns (value, chosen) or None if over budget."""
    bestv = [-1]
    bestm = [0]
    nodes = [0]
    over = []

    r = list(r0)
    gv = 0
    gm = 0
    for i in range(n):
        u = usage[i]
        if _fit(u, r):
            for k in u:
                r[k] -= 1
            gv += b[i]
            gm |= 1 << i
    bestv[0] = gv
    bestm[0] = gm

    def dfs(i, r, cv, mask):
        nodes[0] += 1
        if nodes[0] > limit:
            over.append(1)
            raise _Over()
        if cv > bestv[0]:
            bestv[0] = cv
            bestm[0] = mask
        if i == n:
            return
        u = usage[i]
        bi = b[i]
        if _fit(u, r):
            r2 = _dec(u, r)
            t = cv + bi
            thr = bestv[0] - t
            if thr < 0 or bound(i + 1, r2, thr) > thr:
                dfs(i + 1, r2, t, mask | (1 << i))
            if over:
                return
        thr = bestv[0] - cv
        if thr < 0 or bound(i + 1, r, thr) > thr:
            dfs(i + 1, r, cv, mask)

    try:
        dfs(0, r0, 0, 0)
    except _Over:
        return None
    return bestv[0], tuple(i for i in range(n) if bestm[0] >> i & 1)


class _Over(Exception):
    __slots__ = ()


def _plan_dp(b, usage, K, n, r0, bound):
    """Exact memoised DP; used as a fallback.  Returns (value, chosen)."""
    memo = {}
    mget = memo.get

    def rec(i, r):
        if i == n:
            return 0
        key = (i, r)
        got = mget(key)
        if got is not None:
            return got
        best = rec(i + 1, r)
        u = usage[i]
        if _fit(u, r):
            bi = b[i]
            r2 = _dec(u, r)
            thresh = best - bi
            if bound(i + 1, r2, thresh) > thresh:
                val = bi + rec(i + 1, r2)
                if val > best:
                    best = val
        if len(memo) < MEMO_CAP:
            memo[key] = best
        return best

    rec(0, r0)
    sel = []
    r = r0
    for i in range(n):
        if not _fit(usage[i], r):
            continue
        r2 = _dec(usage[i], r)
        if b[i] + rec(i + 1, r2) > rec(i + 1, r):
            sel.append(i)
            r = r2
    return 0, tuple(sel)


def _plan_search(b, usage, K, n, r0):
    """Exact lexicographic (benefit desc, count asc) maximisation over candidates.

    b holds transformed weights benefit*mult-1 (mult>n) so a single scalar
    maximisation encodes both documented objectives.
    """
    if n == 0:
        return 0, ()
    bound = _bound_tables(b, usage, K, n)
    res = _plan_bnb(b, usage, K, n, r0, bound, BNB_LIMIT)
    if res is None:
        res = _plan_dp(b, usage, K, n, r0, bound)
    return res


